 ('PER_IAM','I AM Activity & Ascended-Master New Religions',1930,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_MELTON_AMERICAN_RELIGIONS','secondary scholarship','J. Gordon Melton, Encyclopedia of American Religions (8th ed., Gale, 2009)','Scholarly reference on the I AM Activity, Church Universal and Triumphant, and the Ascended-Master family of new religious movements'),
 ('SRC_PROPHET_SAINT_GERMAIN_ALCHEMY','primary text','Mark L. Prophet & Elizabeth Clare Prophet, Saint Germain On Alchemy: Formulas for Self-Transformation (Summit University Press, 1985)','Devotional/instructional primary text of Church Universal and Triumphant on the Mighty I AM Presence, the Violet Flame, and Saint Germain as Aquarian-age hierarch')
INSERT INTO _e VALUES
 ('ENT_IAM_GREAT_WHITE_BROTHERHOOD','The Great White Brotherhood','collective','collective','Theosophical','spiritual hierarchy; ascended masters; planetary governance','B','Named collective of the Ascended Masters as taught and devotionally invoked in the I AM Activity (Ballard) and Church Universal and Triumphant (the Prophets); ''White'' denotes the aura/light, not race. Hub entity for the I AM/CUT layer.'),
 ('ENT_IAM_MIGHTY_I_AM_PRESENCE','The Mighty I AM Presence','divine principle','divine principle','Theosophical','individualized God-presence; divine self; source of the lifestream','B','The individualized God-presence above each person, central object of decree and devotion in the I AM Activity and CUT (the upper figure of the ''Chart of Your Divine Self'').'),
 ('ENT_IAM_VIOLET_FLAME','The Violet Flame','divine principle','divine principle','Theosophical','transmutation; mercy ray; spiritual alchemy; karmic purification','B','The seventh-ray transmuting flame invoked through decrees in the I AM Activity and CUT; associated with Saint Germain and used ritually for transmutation of karma.'),
 ('ENT_IAM_NADA','Lady Master Nada','ascended master','ascended master','Theosophical','sixth ray; ministration and service; divine love','C','Ascended Lady Master and Chohan of the sixth ray invoked in CUT devotion; one of the Ascended Lady Masters of the I AM/CUT hierarchy. Distinct from the Israelite figure Nadab (ENT_ISR_NADAB).'),
 ('ENT_IAM_SAINT_GERMAIN_HIERARCH','Saint Germain, Hierarch of the Aquarian Age','ascended master','ascended master','Theosophical','seventh ray; violet flame; freedom; Aquarian-age dispensation','B','Reception within the I AM Activity and CUT of the existing Master Saint Germain as the Chohan of the seventh ray and sponsoring hierarch of the Aquarian age; devotionally invoked, distinct cult-form of the Theosophical Saint Germain (ENT_THE_SAINT_GERMAIN).');
