INSERT INTO _p VALUES
 ('ENT_IAM_GREAT_WHITE_BROTHERHOOD','PER_IAM','Named collective of the Ascended Masters as taught and devotionally invoked in the I AM Activity (Ballard) and Church Universal and Triumphant (the Prophets); ''White'' denotes the aura/light, not race. Hub entity for the I AM/CUT layer.'),
 ('ENT_IAM_MIGHTY_I_AM_PRESENCE','PER_IAM','The individualized God-presence above each person, central object of decree and devotion in the I AM Activity and CUT (the upper figure of the ''Chart of Your Divine Self'').'),
 ('ENT_IAM_VIOLET_FLAME','PER_IAM','The seventh-ray transmuting flame invoked through decrees in the I AM Activity and CUT; associated with Saint Germain and used ritually for transmutation of karma.'),
 ('ENT_IAM_NADA','PER_IAM','Ascended Lady Master and Chohan of the sixth ray invoked in CUT devotion; one of the Ascended Lady Masters of the I AM/CUT hierarchy. Distinct from the Israelite figure Nadab (ENT_ISR_NADAB).'),
 ('ENT_IAM_SAINT_GERMAIN_HIERARCH','PER_IAM','Reception within the I AM Activity and CUT of the existing Master Saint Germain as the Chohan of the seventh ray and sponsoring hierarch of the Aquarian age; devotionally invoked, distinct cult-form of the Theosophical Saint Germain (ENT_THE_SAINT_GERMAIN).');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_IAM_SAINT_GERMAIN_HIERARCH','reception_of','ENT_THE_SAINT_GERMAIN','high','The I AM/CUT Aquarian-age hierarch is a devotional cult-form/reception of the existing Theosophical Master Saint Germain (Rakoczi).'),
 ('ENT_IAM_SAINT_GERMAIN_HIERARCH','member_of','ENT_IAM_GREAT_WHITE_BROTHERHOOD','high','Saint Germain is a chief master of the Great White Brotherhood in I AM/CUT teaching.'),
 ('ENT_IAM_NADA','member_of','ENT_IAM_GREAT_WHITE_BROTHERHOOD','high','Lady Master Nada is enumerated among the Ascended Masters of the Great White Brotherhood.'),
 ('ENT_IAM_GREAT_WHITE_BROTHERHOOD','reception_of','ENT_REC_MAHATMAS','high','The I AM/CUT Great White Brotherhood is the reception of the earlier Theosophical Masters of Wisdom (Mahatmas) as a named devotional collective.'),
 ('ENT_IAM_GREAT_WHITE_BROTHERHOOD','aligned_with','ENT_THE_HIERARCHY','high','The Great White Brotherhood corresponds to the Theosophical Spiritual Hierarchy reframed for the I AM/CUT movements.'),
 ('ENT_THE_MORYA','member_of','ENT_IAM_GREAT_WHITE_BROTHERHOOD','high','El Morya is a primary master of the Great White Brotherhood and was the founding sponsor of CUT (the Summit Lighthouse).'),
 ('ENT_THE_KOOT_HOOMI','member_of','ENT_IAM_GREAT_WHITE_BROTHERHOOD','high','Koot Hoomi (Master K.H.) is invoked as a master of the Great White Brotherhood in I AM/CUT teaching.'),
 ('ENT_THE_SANAT_KUMARA','member_of','ENT_IAM_GREAT_WHITE_BROTHERHOOD','medium','Sanat Kumara is venerated in CUT as a great being associated with the hierarchy of the Great White Brotherhood.'),
 ('ENT_THE_MAITREYA','member_of','ENT_IAM_GREAT_WHITE_BROTHERHOOD','medium','Maitreya, the World Teacher, is counted among the masters of the Great White Brotherhood in I AM/CUT cosmology.'),
 ('ENT_IAM_SAINT_GERMAIN_HIERARCH','presides_over','ENT_IAM_VIOLET_FLAME','high','Saint Germain is the master of the seventh ray and sponsor of the Violet Flame in I AM/CUT devotion.'),
 ('ENT_IAM_VIOLET_FLAME','aligned_with','ENT_THE_SEVEN_RAYS','high','The Violet Flame is the seventh of the Theosophical Seven Rays as developed in the I AM/CUT teaching.'),
 ('ENT_IAM_NADA','aligned_with','ENT_THE_SEVEN_RAYS','medium','Lady Master Nada is identified as Chohan of the sixth of the Seven Rays.'),
 ('ENT_IAM_MIGHTY_I_AM_PRESENCE','aligned_with','ENT_THE_SOLAR_LOGOS','low','The Mighty I AM Presence as the individualized God-self is loosely correlated with the higher divine source in the broader Theosophical cosmology.'),
 ('ENT_IAM_MIGHTY_I_AM_PRESENCE','presides_over','ENT_IAM_VIOLET_FLAME','medium','In I AM/CUT decree practice the Violet Flame is invoked in the name of and through the Mighty I AM Presence.');
